import * as fs from 'fs';

const data = {
  contratante: {
    numero: '00000000000000',
    tipo: 2,
  },
  autorPedidoDados: {
    numero: '00000000000000',
    tipo: 2,
  },
  contribuinte: {
    numero: '00000000000000',
    tipo: 2,
  },
  pedidoDados: {
    dados: '',
    idServico: 'EMITIRCCMEI121',
    idSistema: 'CCMEI',
  },
  mensagens: [
    {
      codigo: '[Sucesso-CCMEI-SUC-00010]',
      texto: 'Requisição efetuada com sucesso.',
    },
  ],
  status: '200',
  dados:
    '[{"cnpj":"00000000000000","pdf":""}]',
};

const response = data;

// o campo dados também é uma string
const dados = JSON.parse(response.dados);

// pega o base64 do pdf
const pdfBase64 = dados[0].pdf;

// converte para bytes
const pdfBuffer = Buffer.from(pdfBase64, 'base64');

// salva
fs.writeFileSync('das.pdf', pdfBuffer);

console.log('PDF salvo!');
